import { createEntityAdapter, createSlice } from '@reduxjs/toolkit';

// Create the adapter with optional configuration
const usersAdapter = createEntityAdapter({
  // Tell the adapter how to get the ID (defaults to entity.id)
  selectId: (user) => user.userId,
  // Optional: keep entries sorted by this comparer function
  sortComparer: (a, b) => a.name.localeCompare(b.name)
});

// Get the pre-built initial state
const initialState = usersAdapter.getInitialState({
  // You can add additional fields to the slice state
  loading: false,
  error: null
});

// Use the adapter in a slice
const usersSlice = createSlice({
  name: 'users',
  initialState,
  reducers: {
    // These are pre-built adapter methods
    addUser: usersAdapter.addOne,
    addUsers: usersAdapter.addMany,
    setAllUsers: usersAdapter.setAll,
    updateUser: usersAdapter.updateOne,
    removeUser: usersAdapter.removeOne,
    removeAllUsers: usersAdapter.removeAll
  }
});

export const {
  addUser,
  updateUser,
  removeUser
} = usersSlice.actions;

export default usersSlice.reducer;

import { createSelector } from '@reduxjs/toolkit';

// Create a selector factory for this entity slice
const usersSelectors = usersAdapter.getSelectors(
  (state) => state.users
);

// These are the pre-built selectors
export const selectAllUsers = usersSelectors.selectAll;
export const selectUserById = usersSelectors.selectById;
export const selectUserIds = usersSelectors.selectIds;
export const selectTotalUserCount = usersSelectors.selectTotal;
export const selectUserEntities = usersSelectors.selectEntities;

// Usage in a component
const users = useSelector(selectAllUsers);
const specificUser = useSelector((state) => selectUserById(state, 'user-123'));

// Basic field update
dispatch(updateUser({
  id: 'user-123',
  changes: { name: 'Alice Smith', email: 'alice@example.com' }
}));

// Update with a function for computed changes
dispatch(updateUser({
  id: 'user-123',
  changes: {
    lastLogin: new Date().toISOString(),
    loginCount: (state, id) => state.users.byId[id].loginCount + 1
  }
}));

// Multiple updates at once
dispatch(usersAdapter.updateMany([
  { id: 'user-1', changes: { role: 'admin' } },
  { id: 'user-2', changes: { role: 'moderator' } }
]));
